def convolve_valid(input_matrix, kernel_matrix):
    input_rows = len(input_matrix)
    input_cols = len(input_matrix[0]) if input_rows > 0 else 0
    kernel_rows = len(kernel_matrix)
    kernel_cols = len(kernel_matrix[0]) if kernel_rows > 0 else 0

    if kernel_rows > input_rows or kernel_cols > input_cols:
        raise ValueError("Kernel is oversized")

    flipped = [row[::-1] for row in kernel_matrix[::-1]]

    out_rows = input_rows - kernel_rows + 1
    out_cols = input_cols - kernel_cols + 1

    output = [[0] * out_cols for _ in range(out_rows)]

    for i in range(out_rows):
        for j in range(out_cols):
            total = 0
            for kr in range(kernel_rows):
                for kc in range(kernel_cols):
                    total += input_matrix[i + kr][j + kc] * flipped[kr][kc]
            output[i][j] = total

    return output
